  Ltac reg_caseRE :=
    cbn [nth srRE0 allregs32];
    first [ rewrite spxRE_val
          | lazymatch goal with |- _ = edenot _ (EVar ?n) =>
              change (edenot E (EVar n)) with (ev E n);
